<?php
namespace App\Http\Controllers;

use App\Models\{ActivityLog,Appointment,Customer,Device,RepairRecord,User};
use App\Http\Requests\{ConfirmAppointmentRequest,StoreCustomerRequest,StoreAppointmentRequest,StoreDeviceRequest,StoreRepairRecordRequest,UpdateCustomerRequest,UpdateDeviceRequest,UpdateProfileRequest,UpdateRepairRecordRequest,WalkInCustomerRequest};
use Illuminate\Http\Request;
use Illuminate\Auth\Access\AuthorizationException;
use Illuminate\Support\Facades\{Auth,DB,Gate,Hash};

class RepairManagementController extends Controller
{
    private function customer(): Customer { return Auth::user()->customer()->firstOrFail(); }
    public function dashboard(Request $request){$canManageRepairs=Gate::allows('manage-repairs');$admin=Gate::allows('manage-accounts');$customer=Auth::user()->customer;abort_unless($canManageRepairs||$customer,403);
        $customerOptions=Customer::with('user')->whereHas('user',fn($q)=>$q->where('role','customer'))->orderBy('last_name')->get();
        $customers=Customer::with('user')->whereHas('user',fn($q)=>$q->where('role','customer'))->when($canManageRepairs&&$request->filled('search'),fn($q)=>$q->where(fn($q)=>$q->where('first_name','like','%'.$request->search.'%')->orWhere('last_name','like','%'.$request->search.'%')->orWhere('contact_number','like','%'.$request->search.'%')->orWhereHas('user',fn($q)=>$q->where('email','like','%'.$request->search.'%'))))->when($canManageRepairs,fn($q)=>$q->orderBy('last_name'),fn($q)=>$q->where('customer_id',$customer->customer_id))->paginate(10,['*'],'customers_page')->withQueryString();
        $deviceQuery=Device::with('customer')->when(!$canManageRepairs,fn($q)=>$q->where('customer_id',$customer->customer_id));
        $devices=(clone $deviceQuery)->get();
        $registeredDevices=(clone $deviceQuery)->latest('device_id')->paginate(10,['*'],'devices_page')->withQueryString();
        $appointments=Appointment::with(['customer.user','device','repairRecord'])->when(!$canManageRepairs,fn($q)=>$q->where('customer_id',$customer->customer_id))->when($canManageRepairs,fn($q)=>$q->where('status','!=','Completed')->whereDoesntHave('repairRecord',fn($q)=>$q->where('repair_status','Completed')))->when($canManageRepairs&&$request->filled('status'),fn($q)=>$q->where('status',$request->status))->when($canManageRepairs&&$request->filled('from'),fn($q)=>$q->whereDate('preferred_date','>=',$request->from))->when($canManageRepairs&&$request->filled('to'),fn($q)=>$q->whereDate('preferred_date','<=',$request->to))->when($canManageRepairs&&$request->filled('search'),fn($q)=>$q->whereHas('customer',fn($q)=>$q->where('first_name','like','%'.$request->search.'%')->orWhere('last_name','like','%'.$request->search.'%')))->latest()->paginate(10,['*'],'appointments_page')->withQueryString();
        $repairs=RepairRecord::with(['device.customer.user','appointment'])->when(!$canManageRepairs,fn($q)=>$q->whereHas('device',fn($q)=>$q->where('customer_id',$customer->customer_id)))->when($canManageRepairs&&$request->filled('repair_status'),fn($q)=>$q->where('repair_status',$request->repair_status))->when($canManageRepairs&&$request->filled('from'),fn($q)=>$q->whereDate('created_at','>=',$request->from))->when($canManageRepairs&&$request->filled('to'),fn($q)=>$q->whereDate('created_at','<=',$request->to))->when($canManageRepairs&&$request->filled('search'),fn($q)=>$q->whereHas('device.customer',fn($q)=>$q->where('first_name','like','%'.$request->search.'%')->orWhere('last_name','like','%'.$request->search.'%')))->latest()->paginate(10,['*'],'repairs_page')->withQueryString();
        $repairQueue=$canManageRepairs?Appointment::with(['customer','device','repairRecord'])->whereIn('status',['Pending','Confirmed','Rescheduled','Completed'])->when($request->filled('search'),fn($q)=>$q->whereHas('customer',fn($q)=>$q->where('first_name','like','%'.$request->search.'%')->orWhere('last_name','like','%'.$request->search.'%')))->when($request->filled('from'),fn($q)=>$q->whereDate('preferred_date','>=',$request->from))->when($request->filled('to'),fn($q)=>$q->whereDate('preferred_date','<=',$request->to))->latest()->get():collect();
        $completedQueue=$repairQueue->filter(fn($appointment)=>(($appointment->repairRecord?->repair_status??($appointment->status==='Completed'?'Completed':'Pending'))==='Completed'))->values();
        $repairQueue=$repairQueue->reject(fn($appointment)=>(($appointment->repairRecord?->repair_status??($appointment->status==='Completed'?'Completed':'Pending'))==='Completed'))->values();
        $stats=$canManageRepairs?['customers'=>Customer::whereHas('user',fn($q)=>$q->where('role','customer'))->count(),'pending'=>Appointment::where('status','Pending')->count(),'today'=>Appointment::whereDate('confirmed_date',today())->count(),'repairs'=>RepairRecord::where('repair_status','!=','Completed')->count(),'completed_repairs'=>RepairRecord::where('repair_status','Completed')->count(),'repair_breakdown'=>RepairRecord::selectRaw('repair_status, count(*) as total')->groupBy('repair_status')->pluck('total','repair_status')]:[];
        if(!$canManageRepairs){$stats=['devices'=>$customer->devices()->count(),'pending'=>$customer->appointments()->where('status','Pending')->count(),'repairs'=>RepairRecord::whereHas('device',fn($q)=>$q->where('customer_id',$customer->customer_id))->where('repair_status','!=','Completed')->count()];}
        return view('repair.dashboard',compact('canManageRepairs','admin','customer','customerOptions','customers','devices','registeredDevices','appointments','repairs','repairQueue','completedQueue','stats'));}
    public function register(StoreCustomerRequest $r){$v=$r->validated(); DB::transaction(function()use($v){$u=User::create(['name'=>trim($v['first_name'].' '.$v['last_name']),'email'=>$v['email'],'password'=>Hash::make($v['password']),'role'=>'customer']); Customer::create(['user_id'=>$u->user_id,'first_name'=>$v['first_name'],'last_name'=>$v['last_name'],'contact_number'=>$v['contact_number'],'address'=>$v['address']??null]);}); Auth::attempt($r->only('email','password')); $r->session()->regenerate(); return redirect('/repair');}
    public function login(Request $r){$v=$r->validate(['email'=>'required|email','password'=>'required']); if(!Auth::attempt($v+['is_active'=>true])) return back()->withErrors(['email'=>'Invalid login details.']); $r->session()->regenerate(); return redirect('/repair');}
    public function logout(Request $r){Auth::guard('web')->logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('login')->header('Clear-Site-Data','"cache"')->header('Cache-Control','no-store, no-cache, must-revalidate, private, max-age=0');}
    public function profile(UpdateProfileRequest $r){$v=$r->validated();DB::transaction(function()use($v){Auth::user()->update(['name'=>trim($v['first_name'].' '.$v['last_name'])]);$this->customer()->update($v);});return back()->with('success','Profile updated.');}
    public function device(StoreDeviceRequest $r){$v=$r->validated();$canManageRepairs=Gate::allows('manage-repairs');$c=$canManageRepairs?Customer::findOrFail($v['customer_id']):$this->customer();$device=$c->devices()->create(collect($v)->except('customer_id')->all());$this->logActivity($device->device_type.' registered',$device);return $canManageRepairs?back()->with('success',$device->device_type.' saved.'):redirect('/repair?tab=appointments')->with('success',$device->device_type.' saved.');}
    public function appointment(StoreAppointmentRequest $r){$v=$r->validated();if(isset($v['concern_type'])){$v['concern']=$v['concern_type']==='Other'?trim($v['concern_other']??''):$v['concern_type'];} $d=Device::findOrFail($v['device_id']);$appointment=$d->appointments()->create(['customer_id'=>$d->customer_id,'preferred_date'=>$v['preferred_date'],'preferred_start_time'=>$v['preferred_start_time'],'preferred_end_time'=>$v['preferred_end_time'],'concern'=>$v['concern'],'status'=>'Pending']);$this->logActivity('Appointment submitted',$appointment);return back()->with('success',$d->device_type.' repair appointment submitted.');}
    public function cancelAppointment(Appointment $appointment){try{Gate::authorize('cancel',$appointment);}catch(AuthorizationException $exception){return back()->with('error',$exception->getMessage());}$appointment->update(['status'=>'Cancelled']);$this->logActivity('Appointment cancelled',$appointment);return back()->with('success','Your appointment was cancelled.');}
    public function schedule(ConfirmAppointmentRequest $r,Appointment $appointment){Gate::authorize('manage',$appointment);$appointment->update($r->validated());$this->logActivity('Appointment status updated',$appointment);return back()->with('success','Appointment updated.');}
    public function repair(StoreRepairRecordRequest $r){$v=$r->validated();$a=Appointment::with('repairRecord')->findOrFail($v['appointment_id']);Gate::authorize('manage',$a);if($v['repair_status']==='Completed'&&!($v['date_completed']??null))$v['date_completed']=now()->toDateString();$record=$a->repairRecord()->updateOrCreate([],array_merge($v,['device_id'=>$a->device_id]));if($record->repair_status==='Completed'&&$a->status!=='Completed')$a->update(['status'=>'Completed']);$this->logActivity('Repair record created',$record);return back()->with('success','Repair record saved.');}
    public function updateRepair(UpdateRepairRecordRequest $r, RepairRecord $repair){$v=$r->validated();if($v['repair_status']==='Completed'&&!($v['date_completed']??null))$v['date_completed']=now()->toDateString();$repair->update($v);if($repair->repair_status==='Completed'&&$repair->appointment&&$repair->appointment->status!=='Completed')$repair->appointment->update(['status'=>'Completed']);$this->logActivity('Repair status updated',$repair);return back()->with('success','Repair progress updated.');}
    public function walkin(WalkInCustomerRequest $r){$v=$r->validated();$c=DB::transaction(function()use($v){$u=User::create(['name'=>trim($v['first_name'].' '.$v['last_name']),'email'=>$v['email'],'password'=>Hash::make($v['password']??str()->random(20)),'role'=>'customer']);return Customer::create(['user_id'=>$u->user_id,'first_name'=>$v['first_name'],'last_name'=>$v['last_name'],'contact_number'=>$v['contact_number'],'address'=>$v['address']??null]);});$this->logActivity('Customer registered',$c);return back()->with('success','Customer registered (#'.$c->customer_id.').');}
    public function updateCustomer(UpdateCustomerRequest $r, Customer $customer){$v=$r->validated();DB::transaction(function()use($customer,$v){$customer->user->update(['name'=>trim($v['first_name'].' '.$v['last_name'])]);$customer->update($v);});$this->logActivity('Customer information updated',$customer);return back()->with('success','Customer information updated.');}
    public function updateDevice(UpdateDeviceRequest $r, Device $device){$device->update($r->validated());$this->logActivity($device->device_type.' details updated',$device);return back()->with('success',$device->device_type.' details updated.');}
    public function reports(Request $r){$r->validate(['from'=>'nullable|date','to'=>'nullable|date|after_or_equal:from']);$appointments=Appointment::with(['customer','device'])->when($r->filled('from'),fn($q)=>$q->whereDate('preferred_date','>=',$r->from))->when($r->filled('to'),fn($q)=>$q->whereDate('preferred_date','<=',$r->to))->orderBy('preferred_date')->paginate(15,['*'],'appointments_page')->withQueryString();$repairs=RepairRecord::with(['appointment.customer','device'])->where('repair_status','Completed')->when($r->filled('from'),fn($q)=>$q->whereDate('date_completed','>=',$r->from))->when($r->filled('to'),fn($q)=>$q->whereDate('date_completed','<=',$r->to))->orderBy('date_completed')->paginate(15,['*'],'repairs_page')->withQueryString();return view('repair.reports',compact('appointments','repairs'));}
    private function logActivity(string $action, $model): void{ActivityLog::create(['user_id'=>Auth::id(),'action'=>$action,'model'=>class_basename($model).'#'.$model->getKey()]);}
}
